<script setup lang="ts">
import {ref,computed,onMounted} from 'vue'
import {promptApi,type AuthorPrompt,type PromptSelection} from './prompt-api'
import {useRequestScope} from '../platform/request-scope'
const props=defineProps<{worldId:string}>(),capture=useRequestScope(()=>props.worldId),items=ref<AuthorPrompt[]>([]),selection=ref<PromptSelection>({version:0,promptIds:[]}),loading=ref(true),busy=ref(false),error=ref(''),notice=ref('')
const selected=computed(()=>items.value.filter(p=>selection.value.promptIds.includes(p.id))),bytes=computed(()=>selected.value.reduce((n,p)=>n+p.utf8Bytes,0))
async function load(){const scope=capture();error.value='';loading.value=true;try{const [p,s]=await Promise.all([promptApi.list(),promptApi.selection(props.worldId)]);if(scope.valid()){items.value=p.items.filter(p=>p.status==='active');selection.value=s}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())loading.value=false}}
function toggle(id:string){if(busy.value)return;const ids=selection.value.promptIds;selection.value={...selection.value,promptIds:ids.includes(id)?ids.filter(i=>i!==id):[...ids,id]}}
async function save(){const scope=capture();busy.value=true;error.value='';notice.value='';try{const result=await promptApi.select(props.worldId,selection.value);if(scope.valid()){selection.value=result;notice.value='已保存，下次开始新回合时使用。已排队的任务保持原来的版本。'}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
onMounted(load)
</script>
<template><div class="prompt-selector"><div class="workspace-pills"><span class="capability-badge" data-status="ready">我的提示词</span><span class="capability-badge" data-status="planned">公开库暂未开放</span></div><p class="product-note">{{selection.promptIds.length}} / 20 项 · {{selected.reduce((n,p)=>n+p.characters,0)}} 字符。只影响叙事风格，不改变已确认的世界状态。</p><p v-if="loading" role="status">正在加载提示词…</p><p v-if="error" class="error" role="alert">{{error}} <button :disabled="busy" @click="load">重新加载</button></p><p v-if="notice" role="status" class="product-hint">{{notice}}</p><p v-if="!loading&&!items.length">还没有私人草稿。</p><label v-for="p in items" :key="p.id" class="prompt-option"><input type="checkbox" :checked="selection.promptIds.includes(p.id)" :disabled="busy||(!selection.promptIds.includes(p.id)&&selection.promptIds.length>=20)" @change="toggle(p.id)"><span><strong>{{p.title}}</strong><small>{{p.description||'私人写作偏好'}} · {{p.characters}} 字符</small></span></label><p v-if="bytes>12000" class="error" role="alert">启用内容超过 12 KB，请减少或精简提示词。</p><button class="primary" :disabled="loading||busy||bytes>12000" @click="save">{{busy?'正在保存…':'保存启用列表'}}</button></div></template>
